"""YAML renderer — standard-library only (no PyYAML dependency)."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Render a single scalar value as a YAML scalar string."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return _format_float(value)
    if isinstance(value, str):
        return _yaml_string(value)
    return str(value)


def _format_float(v: float) -> str:
    """Format a float so that YAML parsers read it back correctly."""
    if v != v:
        return ".nan"
    if v == float("inf"):
        return ".inf"
    if v == float("-inf"):
        return "-.inf"
    s = repr(v)
    # repr may give '1.0' which is fine; ensure we don't lose precision.
    return s


def _yaml_string(s: str) -> str:
    """Return a properly quoted YAML scalar string."""
    # Strings that look like other YAML types must be quoted.
    if s == "":
        return '""'
    # Check if the string is safe unquoted (no special chars, not a keyword).
    if _is_safe_unquoted(s):
        return s
    # Use single quotes; escape internal single quotes by doubling them.
    escaped = s.replace("'", "''")
    return f"'{escaped}'"


def _is_safe_unquoted(s: str) -> bool:
    """Return True if *s* can be emitted as an unquoted YAML scalar."""
    # YAML reserved indicators that force quoting.
    if s[0] in ("&", "*", "!", "|", ">", "'", '"', "%", "@", "`", ",",
                 "[", "]", "{", "}", "#", "-", "?", "\n", "\r"):
        return False
    # Keywords that must be quoted.
    _keywords = {
        "null", "Null", "NULL", "~",
        "true", "True", "TRUE",
        "false", "False", "FALSE",
        "yes", "Yes", "YES",
        "no", "No", "NO",
        "on", "On", "ON",
        "off", "Off", "OFF",
    }
    if s in _keywords:
        return False
    # Must not look like a number.
    try:
        int(s)
        return False
    except ValueError:
        pass
    try:
        float(s)
        return False
    except ValueError:
        pass
    return True


def _yaml_dump(rows: list[dict]) -> str:
    """Dump a list of flat dicts into a YAML string (standard-library only)."""
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for key, value in row.items():
            lines.append(f"  {key}: {_yaml_scalar(value)}")
    return "\n".join(lines) + "\n" if lines else ""


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_dump(rows)

