"""Minimal YAML renderer for a list of flat dictionaries.

Standard-library only: writes a simple YAML representation without
requiring the PyYAML package.
"""

from plugins import PluginError, Renderer, register


def _yaml_value(v):
    """Return a YAML-safe string representation of a scalar value."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    # Treat everything else as a string; quote if it contains special chars
    s = str(v)
    if s == "" or any(c in s for c in ":{}[]&*?|->!%@`,#'\n\r\"\\"):
        # Use double-quoted YAML string with escaped quotes/backslashes
        escaped = s.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'
    return s


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        keys = list(rows[0].keys())
        lines: list[str] = []
        for row in rows:
            if list(row.keys()) != keys:
                raise PluginError("all rows must share the same keys")
            for j, k in enumerate(keys):
                prefix = "- " if j == 0 else "  "
                lines.append(f"{prefix}{k}: {_yaml_value(row[k])}")
        return "\n".join(lines) + "\n"

