"""YAML renderer — standard-library only (uses repr-based output)."""

from . import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Render a single scalar value as a YAML scalar string."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, str):
        # Use single-quoted style; escape internal single quotes by doubling.
        return "'" + value.replace("'", "''") + "'"
    # Fallback: str()
    return str(value)


def _yaml_block(rows: list[dict]) -> str:
    """Render a list of flat dicts as a YAML block sequence of mappings."""
    if not rows:
        return ""
    keys = list(rows[0].keys())
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for k in keys:
            v = row.get(k)
            lines.append(f"  {k}: {_yaml_scalar(v)}")
    return "\n".join(lines)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_block(rows) + "\n"

